        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if (r1-r0 >= 2 and c1-c0 >= 2 and
            all(grid[r0][c] == color for c in range(c0, c1+1)) and
            all(grid[r1][c] == color for c in range(c0, c1+1)) and
            all(grid[r][c0] == color for r in range(r0, r1+1)) and
            all(grid[r][c1] == color for r in range(r0, r1+1))):
            n = sum(grid[r][c] == color for r in range(r0+1, r1)
                    for c in range(c0+1, c1))
            frames.append((color, r0, r1, c0, c1, n))

    sources = [f for f in frames if f[5] > 0]
    if not sources:
        return grid
    source = max(sources, key=lambda f: f[5])
    color, r0, r1, c0, c1, _ = source
    pat = [[grid[r][c] == color for c in range(c0+1, c1)]
           for r in range(r0+1, r1)]
    ph, pw = len(pat), len(pat[0])
    out = [row[:] for row in grid]

    for f in frames:
        if f == source:
            continue
        col, a, b, x, y, _ = f
        th, tw = b-a-1, y-x-1
        # Copy the design into similarly sized frames.
        if abs(th-ph) <= 1 and abs(tw-pw) <= 1:
            for i in range(th):
                for j in range(tw):
                    si = min(ph-1, i*ph//th)
                    sj = min(pw-1, j*pw//tw)
                    out[a+1+i][x+1+j] = col if pat[si][sj] else 0
        else:
